Translate the following GNU C++14 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll gcd(ll a, ll b) {
    return b == 0 ? a : gcd(b, a % b);
}

ll nearest_integer(double z) {
    double frac = z - floor(z);
    if (frac <= 0.5) return (ll)floor(z);
    return (ll)ceil(z);
}

tuple<ll, ll> choose_fraction(double x, double y, double n) {
    ll a, b;
    double req = x / y;
    double mn = 1e9;

    if (y <= n) {
        a = (ll)x;
        b = (ll)y;
        return make_tuple(a, b);
    }

    for (ll deno = (ll)n; deno >= 1; --deno) {
        double z = (double)deno * req;
        ll num = nearest_integer(z);
        double now = (double)num / (double)deno;
        double diff = std::abs(now - req);

        if (diff <= mn) {
            mn = diff;
            a = num;
            b = deno;
        }
    }

    return make_tuple(a, b);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);

#ifndef ONLINE_JUDGE
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif

    ll t = 1;
    while (t--) {
        double x, y, n;
        cin >> x >> y >> n;

        ll a, b;
        tie(a, b) = choose_fraction(x, y, n);

        ll g = gcd(a, b);
        a /= g;
        b /= g;

        cout << a << "/" << b << "\n";
    }

    return 0;
}
